// Function Node: Build Worker Task List

const taskDivision = $json.body.taskDivision;
const workers = $json.body.workers;  // Changed: directly access workers array

// Get task division keys (in order)
const taskKeys = Object.keys(taskDivision.tasks);

// Create array of workers with their assigned tasks
const workerTaskList = workers.map((worker, index) => {
  // Map tasks by index: first worker gets first task, etc.
  const taskKey = taskKeys[index] || taskKeys[0];

  return {
    workerName: worker.workerName,
    port: worker.port,
    task: taskDivision.tasks[taskKey],  // Get task by key
    genericTaskName: taskKey,  // Keep track of original task name
    status: worker.status,
    pid: worker.pid
  };
});

return workerTaskList;

