  console.log('[Soldier1] Starting attack loop');
  let hits = 0;
  while (target && target.isValid) {
    if (bot.health < 12) {
      console.log('[Soldier1] Low health, retreating');
      await skills.moveAway(bot, 10);
      break;
    }
    await bot.lookAt(target.position);
    await bot.attack(target);
    hits++;
    if (hits % 3 === 0) console.log('[Soldier1] Hits: ' + hits);
    await skills.wait(bot, 300);
    target = bot.entities[target.id];
  }
  console.log('[Soldier1] Combat done, total hits: ' + hits);
} else {
  console.log('[Soldier1] ERROR: No iron_golem found within 50 blocks!');
}

